            if (specMatches > benefitMatches * 2) { balanceText = "Heavy Spec"; balanceClass = "badge-warning"; }
            else if (benefitMatches > specMatches * 2) { balanceText = "Heavy Benefit"; balanceClass = "badge-warning"; }
        }

        // 3. Claim Verification
        let unverifiedCount = 0;
        if (claimsText && specs.length > 0) {
            // Check for aggressive standard marketing triggers
            const aggressiveClaims = [/100%/i, /completely/i, /always/i, /never/i, /best/i, /fastest/i];
            aggressiveClaims.forEach(regex => {
                if (regex.test(claimsText)) {
                    warnings.push({text: `Absolute claim detected ("${claimsText.match(regex)[0]}"). Ensure legally defensible.`, type: 'alert-warning'});
                }
            });

            // Rough heuristic check to see if key specs are missing from matching copy
            specs.forEach(spec => {
                const words = spec.split(' ').filter(w => w.length > 2);
                let matched = false;
                if (words.length > 0) {
                    matched = words.some(word => claimsText.toLowerCase().includes(word));
                }
                if (!matched && words.length > 0) {
                    // Spec is omitted from marketing copy
                }
            });
        }

        // 4. Calculate Readiness Score
        let score = 0;
        if (name) score += 20;
        if (specs.length > 0) score += 30;
        if (claimsText) score += 30;
        if (claimsText && warnings.length === 0) score += 20;
        if (claimsText && warnings.length > 0) score -= (warnings.length * 5);
        score = Math.max(0, Math.min(100, score));

        // Render Badges
        const toneContainer = document.getElementById('toneContainer');
        toneContainer.innerHTML = toneBadges.map(b => `<span class="badge ${b.type}">${b.text}</span>`).join('');

        // Render Balance
        const bBadge = document.getElementById('balanceBadge');
        bBadge.innerText = balanceText;
        bBadge.className = `badge ${balanceClass}`;
        document.getElementById('specCount').innerText = `Specs: ${specMatches}`;
        document.getElementById('benefitCount').innerText = `Benefits: ${benefitMatches}`;

        // Render Score
        document.getElementById('readinessScore').innerText = `${score}%`;
        document.getElementById('readinessFill').style.width = `${score}%`;

        // Render Warnings
        const warningsContainer = document.getElementById('warningsContainer');
        if (warnings.length === 0) {
            warningsContainer.innerHTML = claimsText ? `<div class="alert-item alert-success" style="border-left-color:var(--success); color:#4ade80;">✓ Character profiles & structural claims clean.</div>` : `<div style="font-size: 12px; color: var(--text-muted);">Enter data to verify claims.</div>`;
        } else {
            warningsContainer.innerHTML = warnings.map(w => `<div class="alert-item ${w.type}">${w.text}</div>`).join('');
