        // 5. Generate Checklist dynamically
        const checklistContainer = document.getElementById('checklistContainer');
        const items = [
            { id: 'chk1', text: `Verify '${name || 'Product'}' matching vendor manifests` },
            { id: 'chk2', text: "Character count optimized for mobile shelf view (< 120 chars)" },
            { id: 'chk3', text: `Validate all ${specs.length} verified specifications match technical data sheets` },
            { id: 'chk4', text: "Remove or defend any absolute terminology (e.g., '100%', 'never')" }
        ];

        checklistContainer.innerHTML = items.map(item => `
            <div class="check-item">
                <input type="checkbox" id="${item.id}">
                <label for="${item.id}" style="color:var(--text-main); font-weight:normal; text-transform:none; margin:0;">${item.text}</label>
            </div>
        `).join('');
    }

    function downloadChecklist() {
        const name = document.getElementById('prodName').value || 'Product';
        const score = document.getElementById('readinessScore').innerText;
        const claims = document.getElementById('claims').value;

        let manifest = `LAUNCH MANIFEST: ${name.toUpperCase()}\n`;
        manifest += `Readiness Rating: ${score}\n`;
        manifest += `Timestamp: ${new Date().toISOString()}\n\n`;
        manifest += `--- Copy Entry ---\n${claims}\n\n`;
        manifest += `--- Sign-off Tasks ---\n`;

        ['chk1', 'chk2', 'chk3', 'chk4'].forEach(id => {
            const el = document.getElementById(id);
            if (el) {
                const label = el.nextElementSibling.innerText;
                manifest += `[${el.checked ? 'X' : ' '}] ${label}\n`;
            }
        });

        const blob = new Blob([manifest], { type: 'text/plain' });
        const a = document.createElement('a');
        a.href = URL.createObjectURL(blob);
        a.download = `${name.toLowerCase().replace(/\s+/g, '_')}_manifest.txt`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
    }

    // Initialize
    analyze();
</script>
</body>
