                { id: 'chk2', text: "Character count optimized for mobile shelf view (< 120 chars)" },
                { id: 'chk3', text: `Validate all ${specs.length} verified specifications match technical data sheets` },
                { id: 'chk4', text: "Remove or defend any absolute terminology (e.g., '100%', 'never')" }
            ];

            items.forEach(item => {
                const wrapper = document.createElement('div');
                wrapper.className = 'check-item';

                const checkbox = document.createElement('input');
                checkbox.type = 'checkbox';
                checkbox.id = item.id;

                const label = document.createElement('label');
                label.htmlFor = item.id;
                label.style.color = 'var(--text-main)';
                label.style.fontWeight = 'normal';
                label.style.textTransform = 'none';
                label.style.margin = '0';
                label.textContent = item.text;

                wrapper.appendChild(checkbox);
                wrapper.appendChild(label);
                checklistContainer.appendChild(wrapper);
            });
        }

        function downloadChecklist() {
            const name = prodNameInput.value.trim() || 'Product';
            const score = document.getElementById('readinessScore').textContent;
            const claims = claimsInput.value;

            let manifest = `LAUNCH MANIFEST: ${name.toUpperCase()}\n`;
            manifest += `Readiness Rating: ${score}\n`;
            manifest += `Timestamp: ${new Date().toISOString()}\n\n`;
            manifest += `--- Copy Entry ---\n${claims}\n\n`;
            manifest += `--- Sign-off Tasks ---\n`;

            ['chk1', 'chk2', 'chk3', 'chk4'].forEach(id => {
                const el = document.getElementById(id);
                if (el) {
                    const labelText = el.nextElementSibling.textContent;
                    manifest += `[${el.checked ? 'X' : ' '}] ${labelText}\n`;
                }
            });

            const blob = new Blob([manifest], { type: 'text/plain' });
            const a = document.createElement('a');
            a.href = URL.createObjectURL(blob);
            a.download = `${name.toLowerCase().replace(/\s+/g, '_')}_manifest.txt`;
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
        }

        // Run initial parse on blank state
        analyze();
    });
</script>
